query findTools($expression: ExpressionSearchInput, $gene: String) {
  alleles: searchExpressionTools(expression: $expression, gene: $gene) {
    id
    expression_terms {
      id
      name
      __typename
    }
    __typename
  }
}

query getAlleles($fbal_ids: [String]!) {
  alleles: allelesByFbal(ids: $fbal_ids) {
    id
    symbol
    isConstruct
    stocksCount
    pubCount
    knownLesion
    hasImage
    geneIsRegulatoryRegion
    propagateTransgenicUses
    gene {
      id
      symbol
      __typename
    }
    mutagens {
      id
      name
      __typename
    }
    classes {
      id
      name
      __typename
    }
    insertions {
      id
      symbol
      constructs {
        tools {
          id
          symbol
          relType
          toolUses: uses {
            id
            name
            __typename
          }
          __typename
        }
        toolUses {
          id
          name
          __typename
        }
        __typename
      }
      __typename
    }
    constructs {
      id
      symbol
      tools {
        id
        symbol
        relType
        toolUses: uses {
          id
          name
          __typename
        }
        __typename
      }
      toolUses {
        id
        name
        __typename
      }
      __typename
    }
    tools {
      id
      symbol
      relType
      toolUses: uses {
        id
        name
        __typename
      }
      __typename
    }
    toolUses {
      id
      name
      __typename
    }
    __typename
